def longest_pal(seq):
    best=(0,0,0)
    n=len(seq)
    for center in range(n):
        # odd
        i=j=center
        while i>=0 and j<n and seq[i]==seq[j]:
            i-=1; j+=1
        l=j-i-1
        if l>best[0]: best=(l,i+1,'odd')
    for center in range(n-1):
        i,j=center,center+1
        while i>=0 and j<n and seq[i]==seq[j]:
            i-=1; j+=1
        l=j-i-1
        if l>best[0]: best=(l,i+1,'even')
    return best
