import random, math
from collections import Counter
seq = ""
with open("region.fasta") as f:
    for line in f:
        if line.startswith(">"): continue
        seq += line.strip()
n=len(seq)
comp={'A':'T','T':'A','G':'C','C':'G'}
def rc(s): return ''.join(comp[x] for x in reversed(s))
stop={'TAA','TAG','TGA'}

def longest_stopfree(s):
    best=0
    for fr in range(3):
        cur=0
        for i in range(fr,len(s)-2,3):
            if s[i:i+3] in stop:
                best=max(best,cur); cur=0
            else: cur+=1
        best=max(best,cur)
    return best

def longest_homopolymer(s):
    best=0;cur=1
    for i in range(1,len(s)):
        if s[i]==s[i-1]: cur+=1
        else: cur=1
        best=max(best,cur)
    return best

def longest_repeat(s,L=12):
    idx={}
    for i in range(len(s)-L+1):
        idx.setdefault(s[i:i+L],[]).append(i)
    return max((len(v) for v in idx.values()), default=0)

obs_sf = max(longest_stopfree(seq), longest_stopfree(rc(seq)))
obs_hp = longest_homopolymer(seq)
obs_rp = longest_repeat(seq,12)
print("Observed: longest stop-free codons=%d, longest homopolymer=%d, repeats of 12-mer count=%d"%(obs_sf,obs_hp,obs_rp))

