print("Longest true DNA palindrome (rc=itself): len %d at 0-based %d..%d (1-based %d..%d)"%(best[0],best[1],best[1]+best[0]-1,best[1]+1,best[1]+best[0]))
print("  seq:", seq[best[1]:best[1]+best[0]])
